#pragma once

// PROTOTYPE (claude/text-emboss-prototype): builds raised or cut text for an
// object from a string, synchronously, with libslic3r's public text functions
// only. Not wired to any tool.

#include <libslic3r/EmbossShape.hpp>
#include <libslic3r/Point.hpp>
#include <libslic3r/TextConfiguration.hpp>
#include <libslic3r/TriangleMesh.hpp>

#include <optional>
#include <string>

namespace Slic3r::GUI::JusPrin::Workspace {

struct TextShapeRequest
{
    std::string text;      // UTF-8, may hold '\n'
    std::string font_path; // a .ttf or .ttc file
    Vec3d       center;    // world mm, a point on the face
    Vec3d       normal;    // world, out of the face
    double      size  = 10.; // mm, the font's em size (OrcaSlicer's "height")
    double      depth = 1.;  // mm, how far the letters stand out or cut in
    bool        cut   = false;
};

struct TextShape
{
    // In the text's own frame: x along the line, y up the letters, z out of
    // the face. The face is z = 0.
    TriangleMesh mesh;
    // Text frame to world.
    Transform3d world;
    // What OrcaSlicer's text tool keeps on a text volume.
    EmbossShape       emboss_shape;
    TextConfiguration text_configuration;
    // Characters of the text the font has no letter for, in order, UTF-8.
    std::string missing;
};

// On failure returns nothing and says why in `problem`.
std::optional<TextShape> build_text_shape(const TextShapeRequest& request, std::string& problem);

} // namespace Slic3r::GUI::JusPrin::Workspace

#include "TextShape.hpp"

#include <libslic3r/Emboss.hpp>

#include <boost/nowide/convert.hpp>

#include <memory>
#include <utility>

namespace Slic3r::GUI::JusPrin::Workspace {

namespace {

// How far the letters reach past the face, so a raised letter fuses with the
// face and a cut opens through it. OrcaSlicer's text job uses the same value
// (SAFE_SURFACE_OFFSET, file-local in EmbossJob.cpp).
constexpr double kSurfaceOverlap = 0.015; // mm

std::string missing_letters(const std::string& text, const Emboss::FontFile& font)
{
    std::string missing;
    for (wchar_t letter : boost::nowide::widen(text)) {
        if (letter == L'\n' || letter == L'\r' || letter == L'\t' || letter == L' ')
            continue;
        bool unknown = false;
        Emboss::create_range_text(boost::nowide::narrow(std::wstring(1, letter)), font, 0, &unknown);
        if (unknown)
            missing += boost::nowide::narrow(std::wstring(1, letter));
    }
    return missing;
}

} // namespace

std::optional<TextShape> build_text_shape(const TextShapeRequest& request, std::string& problem)
{
    std::unique_ptr<Emboss::FontFile> font = Emboss::create_font_file(request.font_path.c_str());
    if (!font) {
        problem = "the font could not be loaded";
        return std::nullopt;
    }

    TextShape result;
    result.missing = missing_letters(request.text, *font);

    FontProp prop(static_cast<float>(request.size));
    result.text_configuration.text  = request.text;
    result.text_configuration.style = EmbossStyle{"JusPrin", request.font_path, EmbossStyle::Type::file_path, prop};

    Emboss::FontFileWithCache font_with_cache(std::move(font));
    EmbossShape&              shape = result.emboss_shape;
    shape.shapes_with_ids           = Emboss::text2vshapes(font_with_cache, boost::nowide::widen(request.text), prop);
    shape.scale                     = Emboss::get_text_shape_scale(prop, *font_with_cache.font_file);
    shape.projection.depth          = request.depth;
    shape.projection.use_surface    = false;

    // The rest is the mesh step of OrcaSlicer's text job (try_create_mesh in
    // EmbossJob.cpp), without its stand-in mesh for empty text.
    const ExPolygons outline = union_with_delta(shape, Emboss::UNION_DELTA, Emboss::UNION_MAX_ITERATIN);
    if (outline.empty()) {
        problem = "the text makes no letters in this font";
        return std::nullopt;
    }
    Emboss::ProjectScale project(std::make_unique<Emboss::ProjectZ>(request.depth / shape.scale), shape.scale);
    indexed_triangle_set its = Emboss::polygons2model(outline, project);
    const float          z   = static_cast<float>(request.cut ? kSurfaceOverlap - request.depth : -kSurfaceOverlap);
    for (stl_vertex& vertex : its.vertices)
        vertex.z() += z;
    result.mesh  = TriangleMesh(std::move(its));
    result.world = Emboss::create_transformation_onto_surface(request.center, request.normal.normalized());
    return result;
}

} // namespace Slic3r::GUI::JusPrin::Workspace

