// PROTOTYPE probe for TextShape (claude/text-emboss-prototype). Not part of
// any CMake target; compiled by hand against an existing libslic3r build.
//
// For each case: builds the text, measures it, adds it to a box object as a
// part or negative part, slices the object with and without the text and
// draws the layers' difference as an SVG picture.
//
//   text_shape_probe <fonts dir> <out dir>

#include "slic3r/GUI/JusPrin/Workspace/TextShape.hpp"

#include <libslic3r/ClipperUtils.hpp>
#include <libslic3r/Emboss.hpp>
#include <libslic3r/Format/bbs_3mf.hpp>
#include <libslic3r/Geometry.hpp>
#include <libslic3r/Layer.hpp>
#include <libslic3r/Model.hpp>
#include <libslic3r/Print.hpp>
#include <libslic3r/PrintConfig.hpp>
#include <libslic3r/TriangleMesh.hpp>
#include <libslic3r/Utils.hpp>

#include <chrono>
#include <cmath>
#include <cstdio>
#include <fstream>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>

using namespace Slic3r;
using Slic3r::GUI::JusPrin::Workspace::TextShape;
using Slic3r::GUI::JusPrin::Workspace::TextShapeRequest;
using Slic3r::GUI::JusPrin::Workspace::build_text_shape;

namespace {

using Clock = std::chrono::steady_clock;
double ms_since(Clock::time_point t) { return std::chrono::duration<double, std::milli>(Clock::now() - t).count(); }

struct Case
{
    std::string name, text, font;
    bool        side = false; // on the front face (-Y) instead of the top
    bool        cut  = false;
    double      size = 10., depth = 1.;
    double      turn_deg = 0.;         // object turned about Z
    Vec3d       scale{1., 1., 1.};     // object scaled
    Vec3d       box{90., 30., 15.};
    bool        slice = true;
    bool        save_3mf = false;
};

ModelObject& add_box(Model& model, const Case& c)
{
    ModelObject* object = model.add_object();
    object->name        = "box";
    TriangleMesh mesh   = make_cube(c.box.x(), c.box.y(), c.box.z());
    mesh.translate(float(-c.box.x() / 2), float(-c.box.y() / 2), float(-c.box.z() / 2));
    ModelVolume* part = object->add_volume(std::move(mesh), ModelVolumeType::MODEL_PART, false);
    part->name        = "box";
    ModelInstance* instance = object->add_instance();
    instance->set_offset(Vec3d(128., 128., c.box.z() * c.scale.z() / 2));
    instance->set_rotation(Vec3d(0., 0., Geometry::deg2rad(c.turn_deg)));
    instance->set_scaling_factor(c.scale);
    return *object;
}

// The face's centre and outward normal in world, the way a caller would
// get them from the object as it stands.
void face(const ModelObject& object, const Case& c, Vec3d& center, Vec3d& normal)
{
    const Transform3d inst = object.instances.front()->get_matrix();
    const Vec3d local_point  = c.side ? Vec3d(0., -c.box.y() / 2, 0.) : Vec3d(0., 0., c.box.z() / 2);
    const Vec3d local_normal = c.side ? Vec3d(0., -1., 0.) : Vec3d(0., 0., 1.);
    center = inst * local_point;
    normal = (inst.linear().inverse().transpose() * local_normal).normalized();
}

ExPolygons world_slices(const PrintObject& po, const Layer& layer)
{
    ExPolygons out = layer.lslices;
    const Point shift = po.instances().front().shift;
    for (ExPolygon& e : out)
        e.translate(shift);
    return out;
}

const Layer* layer_near(const PrintObject& po, double z)
{
    const Layer* best = nullptr;
    for (const Layer* l : po.layers())
        if (!best || std::abs(l->slice_z - z) < std::abs(best->slice_z - z))
            best = l;
    return best;
}

std::string path_of(const ExPolygons& shapes, std::function<Vec2d(const Point&)> map)
{
    std::ostringstream d;
    auto poly = [&](const Polygon& p) {
        for (size_t i = 0; i < p.points.size(); ++i) {
            const Vec2d q = map(p.points[i]);
            d << (i ? "L" : "M") << q.x() << "," << q.y();
        }
        d << "Z";
    };
    for (const ExPolygon& e : shapes) {
        poly(e.contour);
        for (const Polygon& h : e.holes)
            poly(h);
    }
    return d.str();
}

struct Print1
{
    Model model;
    Print print;
};

bool slice(Print1& p, std::string& error)
{
    DynamicPrintConfig config = DynamicPrintConfig::full_print_config();
    config.set_deserialize_strict({{"layer_height", "0.1"}, {"initial_layer_print_height", "0.2"}, {"enable_support", "0"},
                                   {"skirt_loops", "0"}, {"brim_type", "no_brim"}});
    for (ModelObject* mo : p.model.objects) {
        mo->ensure_on_bed();
        p.print.auto_assign_extruders(mo);
    }
    p.print.apply(p.model, config);
    p.print.set_status_silent();
    auto v = p.print.validate();
    if (!v.string.empty()) {
        error = v.string;
        return false;
    }
    try {
        p.print.process();
    } catch (const std::exception& e) {
        error = e.what();
        return false;
    }
    return true;
}

void write_svg(const std::string& file, double w_mm, double h_mm, const std::string& body)
{
    std::ofstream f(file);
    const double k = 8.; // px per mm
    f << "<svg xmlns='http://www.w3.org/2000/svg' width='" << w_mm * k << "' height='" << h_mm * k << "' viewBox='0 0 " << w_mm << " "
      << h_mm << "'>\n<rect width='100%' height='100%' fill='white'/>\n"
      << body << "</svg>\n";
}

// Picture of what the slicer prints for the text alone: the layers with the
// text minus the layers without it (raised), or the other way round (cut).
std::string picture(const Case& c, const TextShape& t, const PrintObject& with, const PrintObject& without, const std::string& out)
{
    const Vec3d  x_axis = t.world.linear().col(0).normalized();
    const Vec3d  y_axis = t.world.linear().col(1).normalized();
    const Vec3d  origin = t.world.translation();
    std::ostringstream body;
    double       w = 0, h = 0;
    size_t       islands = 0;
    if (!c.side) {
        // One layer, halfway through the letters, seen from above in the
        // text's own axes.
        const double z = c.cut ? origin.z() - c.depth / 2 : origin.z() + c.depth / 2;
        const Layer* lw = layer_near(with, z);
        const Layer* lo = layer_near(without, c.cut ? z : origin.z() - 0.5);
        ExPolygons   a = world_slices(with, *lw), b = world_slices(without, *lo);
        ExPolygons   letters = c.cut ? diff_ex(b, a) : diff_ex(a, b);
        letters          = opening_ex(letters, scaled<float>(0.05));
        islands          = letters.size();
        BoundingBoxf box = BoundingBoxf();
        for (const ExPolygon& e : a)
            for (const Point& p : e.contour.points) {
                const Vec2d q = unscale(p);
                const Vec3d d(q.x() - origin.x(), q.y() - origin.y(), 0.);
                box.merge(Vec2d(d.dot(x_axis), d.dot(y_axis)));
            }
        w = box.size().x() + 4, h = box.size().y() + 4;
        auto map = [&](const Point& p) {
            const Vec2d q = unscale(p);
            const Vec3d d(q.x() - origin.x(), q.y() - origin.y(), 0.);
            return Vec2d(d.dot(x_axis) - box.min.x() + 2, box.max.y() - d.dot(y_axis) + 2);
        };
        body << "<path fill='#ccc' fill-rule='evenodd' d='" << path_of(c.cut ? a : b, map) << "'/>\n";
        body << "<path fill='#c22' fill-rule='evenodd' d='" << path_of(letters, map) << "'/>\n";
    } else {
        // Every layer: the letters' cross-sections, each drawn as its span
        // along the line of text, at its height. Seen from the front.
        double umin = 1e9, umax = -1e9, zmax = 0;
        struct Span { double u0, u1, z0, z1; };
        std::vector<Span> spans;
        for (size_t i = 0; i < with.layers().size(); ++i) {
            const Layer* lw = with.layers()[i];
            const Layer* lo = layer_near(without, lw->slice_z);
            ExPolygons   a = world_slices(with, *lw), b = world_slices(without, *lo);
            ExPolygons   letters = c.cut ? diff_ex(b, a) : diff_ex(a, b);
            letters              = opening_ex(letters, scaled<float>(0.02));
            islands += letters.size();
            for (const ExPolygon& e : letters) {
                double u0 = 1e9, u1 = -1e9;
                for (const Point& p : e.contour.points) {
                    const Vec2d q = unscale(p);
                    const double u = Vec3d(q.x() - origin.x(), q.y() - origin.y(), 0.).dot(x_axis);
                    u0 = std::min(u0, u), u1 = std::max(u1, u);
                }
                spans.push_back({u0, u1, lw->print_z - lw->height, lw->print_z});
                umin = std::min(umin, u0), umax = std::max(umax, u1);
            }
            zmax = std::max(zmax, lw->print_z);
        }
        const double margin = 3;
        umin = std::min(umin, -c.box.x() * c.scale.x() / 2), umax = std::max(umax, c.box.x() * c.scale.x() / 2);
        w = umax - umin + 2 * margin, h = zmax + 2 * margin;
        body << "<rect x='" << margin << "' y='" << margin << "' width='" << umax - umin << "' height='" << zmax << "' fill='#ccc'/>\n";
        for (const Span& s : spans)
            body << "<rect x='" << s.u0 - umin + margin << "' y='" << h - margin - s.z1 << "' width='" << s.u1 - s.u0
                 << "' height='" << s.z1 - s.z0 << "' fill='#c22'/>\n";
    }
    write_svg(out, w, h, body.str());
    return std::to_string(islands);
}

} // namespace

int main(int argc, char** argv)
{
    if (argc < 3) {
        std::cerr << "usage: text_shape_probe <fonts dir> <out dir>\n";
        return 2;
    }
    const std::string fonts = argv[1], out = argv[2];
    set_resources_dir(fonts + "/..");
    const std::string harmony = fonts + "/HarmonyOS_Sans_SC_Bold.ttf";
    const std::string sarabun = fonts + "/Sarabun-SemiBold.ttf";
    const std::string nanum   = fonts + "/NanumGothic-Bold.ttf";

    std::string long_text;
    for (int i = 0; i < 4; ++i)
        long_text += "THE QUICK BROWN FOX JUMPS OVER THE LAZY DOG 0123456789 ";

    std::vector<Case> cases = {
        {"mickey_top_raised", "MICKEY", harmony},
        {"mickey_top_cut", "MICKEY", harmony, false, true},
        {"mickey_top_cut_small", "MICKEY", harmony, false, true, 5., 0.6},
        {"snapon_side_raised", "SNAPON", harmony, true, false, 8., 0.8},
        {"snapon_side_cut", "SNAPON", harmony, true, true, 8., 0.8},
        {"chinese_top_raised", "你好世界", harmony, false, false, 14., 1.},
        {"korean_top_raised", "안녕하세요", nanum, false, false, 12., 1.},
        {"thai_top_raised", "สวัสดี", sarabun, false, false, 14., 1.},
        {"chinese_in_thai_font", "你好", sarabun, false, false, 14., 1.},
        {"mixed_missing", "AB你C", sarabun, false, false, 14., 1.},
        {"two_lines_top", "LINE ONE\nLINE 2", harmony, false, false, 8., 1.},
        {"turned_scaled_top", "MICKEY", harmony, false, false, 10., 1., 30., Vec3d(1.5, 1., 0.8)},
        {"turned_scaled_side", "SNAPON", harmony, true, false, 6., 0.8, 30., Vec3d(1.5, 1., 0.8)},
        {"long_224_chars", long_text, harmony, false, false, 3., 0.6, 0., Vec3d(1, 1, 1), Vec3d(90, 30, 15), false},
        {"font_missing_file", "MICKEY", fonts + "/NoSuchFont.ttf"},
        {"font_not_a_font", "MICKEY", fonts + "/OFL.txt"},
        {"empty_text", "", harmony},
        {"spaces_only", "   ", harmony},
        {"emoji", "\xF0\x9F\x98\x80", harmony},
    };
    cases[0].save_3mf = true;
    cases[1].save_3mf = true;

    std::cout << "case|ok|problem|missing|font_ms|build_ms|triangles|open_edges|parts|volume_mm3|text_w|text_h|world_w|slice_ms|islands\n";
    for (const Case& c : cases) {
        Print1 with;
        ModelObject& object = add_box(with.model, c);
        TextShapeRequest r;
        r.text = c.text, r.font_path = c.font, r.size = c.size, r.depth = c.depth, r.cut = c.cut;
        face(object, c, r.center, r.normal);

        // Font load timed on its own; build_text_shape loads it again.
        auto  t0   = Clock::now();
        auto  font = Emboss::create_font_file(c.font.c_str());
        const double font_ms = ms_since(t0);
        std::string problem;
        t0 = Clock::now();
        std::optional<TextShape> t = build_text_shape(r, problem);
        const double build_ms = ms_since(t0) - (font ? font_ms : 0.);
        if (!t) {
            std::cout << c.name << "|no|" << problem << "||" << font_ms << "|" << build_ms << "|||||||\n";
            continue;
        }
        const indexed_triangle_set& its = t->mesh.its;
        const BoundingBoxf3 local = t->mesh.bounding_box();
        const size_t parts = its_split(its).size();

        ModelVolume* volume = object.add_volume(TriangleMesh(t->mesh), c.cut ? ModelVolumeType::NEGATIVE_VOLUME : ModelVolumeType::MODEL_PART, false);
        volume->name = c.text;
        volume->set_transformation(Geometry::Transformation(object.instances.front()->get_matrix().inverse() * t->world));
        volume->config.set_key_value("extruder", new ConfigOptionInt(0));
        volume->source.is_from_builtin_objects = true;
        volume->emboss_shape       = t->emboss_shape;
        volume->text_configuration = t->text_configuration;
        // Size of the text as it lands in the world.
        const BoundingBoxf3 world_box = t->mesh.transformed_bounding_box(object.instances.front()->get_matrix() * volume->get_matrix());
        const Vec3d x_world = (object.instances.front()->get_matrix() * volume->get_matrix()).linear() * Vec3d(local.size().x(), 0, 0);

        std::string slice_ms = "", islands = "";
        if (c.slice) {
            Print1 without;
            add_box(without.model, c);
            std::string error;
            t0 = Clock::now();
            const bool ok = slice(with, error);
            slice_ms      = std::to_string(int(ms_since(t0)));
            if (ok && slice(without, error)) {
                islands = picture(c, *t, *with.print.objects().front(), *without.print.objects().front(), out + "/" + c.name + ".svg");
            } else
                islands = "slice failed: " + error;
        }
        if (c.save_3mf) {
            StoreParams params;
            params.path   = out + "/" + c.name + ".3mf";
            params.model  = &with.model;
            DynamicPrintConfig config = DynamicPrintConfig::full_print_config();
            params.config = &config;
            params.strategy = SaveStrategy::Silence | SaveStrategy::SplitModel | SaveStrategy::WithGcode | SaveStrategy::ShareMesh;
            params.strategy = SaveStrategy::Zip64;
            const bool stored = store_bbs_3mf(params);
            std::cerr << c.name << ": 3mf " << (stored ? "stored " : "NOT stored ") << params.path << "\n";
            its_write_stl_binary((out + "/" + c.name + "_text.stl").c_str(), "text", its);
        }
        std::cout << c.name << "|yes||" << t->missing << "|" << font_ms << "|" << build_ms << "|" << its.indices.size() << "|"
                  << its_num_open_edges(its) << "|" << parts << "|" << its_volume(its) << "|" << local.size().x() << "|"
                  << local.size().y() << "|" << x_world.norm() << "|" << slice_ms << "|" << islands << "\n";
        (void) world_box;
    }
    return 0;
}

